// Token authority is checked by website-preview BEFORE this function is called.
// The path is read only from the frozen pending release, never the mutable GitHub branch.
export async function frozenPreviewFile(admin:any,siteId:string,path:string,qa=false){
  validateAssetPath(path);
  const h=await hostingMapping(admin,siteId);
  if(!h.pending_release)throw new Error('No verified private release is ready');
  const db=supabaseHostingDatabase(admin),release=await db.release(siteId,h.pending_release);
  if(!release)throw new Error('Frozen preview release metadata is missing');
  const bucket=customerR2Store(h.public_site_id),key=`sites/${h.public_site_id}/release-manifests/${h.pending_release}.json`;
  const marker=await bucket.get(key);
  if(!marker||marker.size>256*1024)throw new Error('Frozen preview completion manifest is unavailable');
  const text=await marker.text();if(await hostingHash(text)!==release.manifest_sha256)throw new Error('Frozen preview manifest changed');
  const manifest=JSON.parse(text);
  if(manifest.site_id!==h.public_site_id||manifest.release!==h.pending_release)throw new Error('Frozen preview belongs to another site');
  if(qa){
    await verifyStagedRelease({bucket,siteId:h.public_site_id,releaseId:h.pending_release});
    return {ok:true,css:true,files:manifest.files.map((f:any)=>f.path),release_id:h.pending_release};
  }
  const file=manifest.files.find((f:any)=>f.path===path);if(!file||file.bytes>7_000_000)throw new Error('Frozen preview file not found');
  const object=await bucket.get(`sites/${h.public_site_id}/releases/${h.pending_release}/${path}`);
  if(!object||object.size!==file.bytes)throw new Error('Frozen preview file is incomplete');
  const bytes=new Uint8Array(await object.arrayBuffer());
  if(bytes.length!==file.bytes||await hostingHash(bytes)!==file.sha256)throw new Error('Frozen preview file checksum mismatch');
  return bytes;
}

import { AwsClient } from 'npm:aws4fetch@1.0.20';
import { createR2S3Store } from './customer-r2.mjs';

// Not wired into production handlers until approvals/DB recovery and live R2 tests pass.
// Credentials must be bucket-scoped Object Read & Write keys in Edge Function Secrets.
export function customerR2Store(siteId: string) {
  if (Deno.env.get('WEBSITE_CUSTOMER_HOSTING') !== 'cloudflare-r2') {
    throw new Error('Cloudflare customer hosting is not enabled');
  }
  const accountId = Deno.env.get('CUSTOMER_R2_ACCOUNT_ID');
  const bucketName = Deno.env.get('CUSTOMER_R2_BUCKET');
  const accessKeyId = Deno.env.get('CUSTOMER_R2_ACCESS_KEY_ID');
  const secretAccessKey = Deno.env.get('CUSTOMER_R2_SECRET_ACCESS_KEY');
  if (!accessKeyId || !secretAccessKey) throw new Error('R2 server credentials are not configured');
  const signer = new AwsClient({accessKeyId, secretAccessKey, region: 'auto', service: 's3', retries: 0});
  return createR2S3Store({accountId, bucketName, siteId, sign: signer.sign.bind(signer)});
}

// Server-only R2 S3 transport for Supabase. No public/upload URL or bucket-wide API.
// The caller still owns admin authorization, persisted approval and publication locks.
const ID = /^[0-9]{4,10}$/;
const RELEASE = /^[a-f0-9]{12,64}$/;
const SHA256 = /^[a-f0-9]{64}$/;
const ETAG = /^"[A-Za-z0-9-]{1,128}"$/;
const encoder = new TextEncoder();
const hex = bytes => Array.from(bytes, b => b.toString(16).padStart(2, '0')).join('');
const digest = async bytes => hex(new Uint8Array(await crypto.subtle.digest('SHA-256', bytes)));

function storageError(code, status, write = false) {
  // Provider bodies/URLs/headers and signer errors may contain secrets. Do not echo them.
  const error = new Error(write
    ? 'R2 write outcome unknown; reconcile stored state before retrying'
    : 'R2 storage request failed');
  error.code = code;
  if (status) error.status = status;
  error.outcomeUnknown = write;
  return error;
}

function keyLimit(key, siteId) {
  const prefix = `sites/${siteId}/`;
  if (typeof key !== 'string' || !key.startsWith(prefix)) throw new Error('R2 key is outside the assigned site');
  const rest = key.slice(prefix.length);
  if (rest === 'active.json') return 4096;
  const manifest = /^release-manifests\/([a-f0-9]+)\.json$/.exec(rest);
  if (manifest && RELEASE.test(manifest[1])) return 256 * 1024;
  const asset = /^releases\/([a-f0-9]+)\/(.+)$/.exec(rest);
  const path = asset?.[2];
  if (!asset || !RELEASE.test(asset[1]) || path.length > 300 || !/^[A-Za-z0-9._/-]+$/.test(path)
      || path.split('/').some(part => !part || part === '.' || part === '..' || part.startsWith('.'))) {
    throw new Error('Unsafe R2 object key');
  }
  return 15 * 1024 * 1024;
}

function objectInfo(response, limit) {
  const rawSize = response.headers.get('content-length');
  const size = rawSize !== null && /^(0|[1-9][0-9]*)$/.test(rawSize) ? Number(rawSize) : NaN;
  const httpEtag = response.headers.get('etag');
  if (!Number.isSafeInteger(size) || size > limit || !ETAG.test(httpEtag || '')) {
    throw storageError('R2_INVALID_RESPONSE');
  }
  const customMetadata = {};
  for (const [name, value] of response.headers) {
    if (name.startsWith('x-amz-meta-')) customMetadata[name.slice(11)] = value;
  }
  return {size, httpEtag, customMetadata};
}

async function readObject(response, info, limit) {
  const parts = [];
  let length = 0;
  const reader = response.body?.getReader();
  if (reader) {
    try {
      for (;;) {
        const {done, value} = await reader.read();
        if (done) break;
        length += value.byteLength;
        if (length > limit || length > info.size) throw storageError('R2_INVALID_RESPONSE');
        parts.push(value);
      }
    } catch {
      await reader.cancel().catch(() => {});
      throw storageError('R2_INVALID_RESPONSE');
    } finally { reader.releaseLock(); }
  }
  if (length !== info.size) throw storageError('R2_INVALID_RESPONSE');
  const bytes = new Uint8Array(length);
  let offset = 0;
  for (const part of parts) { bytes.set(part, offset); offset += part.byteLength; }
  const checksum = info.customMetadata.sha256;
  if (checksum !== undefined && (!SHA256.test(checksum) || await digest(bytes) !== checksum)) {
    throw storageError('R2_CHECKSUM_MISMATCH');
  }
  return {...info, body: new Response(bytes).body,
    text: async () => new TextDecoder().decode(bytes),
    arrayBuffer: async () => bytes.slice().buffer};
}

export function createR2S3Store({accountId, bucketName, siteId, sign, fetch: transport = globalThis.fetch, timeoutMs = 20000}) {
  if (!/^[a-f0-9]{32}$/.test(accountId || '') || !/^[a-z0-9][a-z0-9-]{1,61}[a-z0-9]$/.test(bucketName || '')
      || !ID.test(String(siteId || '')) || typeof sign !== 'function' || typeof transport !== 'function'
      || !Number.isSafeInteger(timeoutMs) || timeoutMs < 1 || timeoutMs > 30000) {
    throw new Error('Invalid server-side R2 configuration');
  }
  const id = String(siteId);
  const origin = `https://${accountId}.r2.cloudflarestorage.com`;
  const objectUrl = key => `${origin}/${bucketName}/${key.split('/').map(encodeURIComponent).join('/')}`;

  async function request(method, key, headers = new Headers(), body, consume = response => response) {
    keyLimit(key, id);
    // GET/HEAD must describe the stored bytes and original strong ETag. Automatic
    // compression/decompression can remove size headers or weaken the ETag used by CAS.
    headers.set('accept-encoding','identity');
    const url = objectUrl(key), controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeoutMs);
    let response;
    try {
      // sign() signs once; AwsClient.fetch() has automatic retries and is deliberately not used.
      const signed = await sign(new Request(url, {method, headers, body, redirect: 'error', signal: controller.signal}),
        {aws: {allHeaders: true}});
      if (!(signed instanceof Request) || signed.url !== url || signed.method !== method) {
        throw storageError('R2_SIGNER_REJECTED');
      }
      // Never forward signed credentials to a redirect destination.
      response = await transport(signed, {redirect: 'error', signal: controller.signal});
      if (response.status >= 300 && response.status < 400) throw storageError('R2_REDIRECT_REJECTED');
      return await consume(response);
    } catch (error) {
      if (typeof error?.code === 'string' && error.code.startsWith('R2_')) throw error;
      throw storageError(method === 'PUT' ? 'R2_WRITE_OUTCOME_UNKNOWN' : 'R2_TRANSPORT_FAILED', undefined, method === 'PUT');
    } finally {
      clearTimeout(timer);
      await response?.body?.cancel().catch(() => {});
    }
  }

  return Object.freeze({
    async head(key) {
      const limit = keyLimit(key, id), response = await request('HEAD', key);
      if (response.status === 404) return null;
      if (response.status !== 200) throw storageError('R2_HTTP_ERROR', response.status);
      return objectInfo(response, limit);
    },
    async get(key) {
      const limit = keyLimit(key, id);
      return request('GET', key, undefined, undefined, async response => {
        if (response.status === 404) { await response.body?.cancel(); return null; }
        if (response.status !== 200) { await response.body?.cancel(); throw storageError('R2_HTTP_ERROR', response.status); }
        return readObject(response, objectInfo(response, limit), limit);
      });
    },
    async put(key, value, options = {}) {
      const limit = keyLimit(key, id);
      if (typeof value !== 'string' && !(value instanceof Uint8Array)) throw new Error('Invalid R2 object content');
      const bytes = typeof value === 'string' ? encoder.encode(value) : value.slice();
      if (!bytes.byteLength || bytes.byteLength > limit) throw new Error('R2 object exceeds its size limit');
      const condition = new Headers(options.onlyIf);
      const ifNone = condition.get('if-none-match'), ifMatch = condition.get('if-match');
      if (!(ifNone === '*' && !ifMatch) && !(key.endsWith('/active.json') && ETAG.test(ifMatch || '') && !ifNone)) {
        throw new Error('A safe conditional R2 write is required');
      }
      const checksum = await digest(bytes);
      if ((options.sha256 !== undefined && options.sha256 !== checksum)
          || (options.customMetadata?.sha256 !== undefined && options.customMetadata.sha256 !== checksum)) {
        throw new Error('R2 content checksum does not match');
      }
      const metadata = {...options.customMetadata, sha256: checksum};
      const headers = new Headers({
        'x-amz-content-sha256': checksum,
        'content-type': options.httpMetadata?.contentType || 'application/octet-stream'
      });
      if (ifNone) headers.set('if-none-match', ifNone);
      if (ifMatch) headers.set('if-match', ifMatch);
      for (const [name, value] of Object.entries(metadata)) {
        if (!/^[a-z0-9-]{1,40}$/.test(name) || typeof value !== 'string' || value.length > 512 || /[^\x20-\x7e]/.test(value)) {
          throw new Error('Invalid R2 object metadata');
        }
        headers.set(`x-amz-meta-${name}`, value);
      }
      const response = await request('PUT', key, headers, bytes);
      if (response.status === 412) return null;
      if (response.status !== 200) throw storageError('R2_HTTP_ERROR', response.status, response.status >= 500);
      const httpEtag = response.headers.get('etag');
      if (!ETAG.test(httpEtag || '')) throw storageError('R2_WRITE_OUTCOME_UNKNOWN', undefined, true);
      return {size: bytes.byteLength, httpEtag, customMetadata: metadata};
    }
  });
}

import {activateRelease,deactivateRelease,fencePublication,readPublication,verifyStagedRelease}
  from './hosting-release-publisher.mjs';

const uuid=/^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/;
const hash=async value=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(value))),x=>x.toString(16).padStart(2,'0')).join('');

export class PublicationUncertainError extends Error {
  constructor(operationId,cause){super('Publication result needs reconciliation',{cause});this.name='PublicationUncertainError';this.operationId=operationId;}
}

// db is a server-side service-role adapter, never a browser client. R2 is scoped to one public site ID.
// A SQL claim is durable across the external call. There is no timeout that silently unlocks it.
export function createHostingPublisher({db,storeForSite}){
  if(!db||typeof storeForSite!=='function')throw new Error('Server database and scoped R2 store required');
  const rpc=async(name,args)=>db.rpc('website_hosting_'+name,args);
  const uncertain=async(id,cause)=>{
    try{await rpc('mark_uncertain',{p_operation:id,p_error:'external_result_unknown'});}catch{/* A DB outage must retain the original durable lock. */}
    return new PublicationUncertainError(id,cause);
  };
  async function authorize(op,actorId=op.actor_id){
    // Membership may have been revoked since the durable claim was created.
    await rpc('require_admin',{p_actor:actorId});
    const [latest,h]=await Promise.all([db.operation(op.operation_id),db.hosting(op.site_id)]);
    return !!latest&&!!h&&['writing','reconcile'].includes(latest.state)
      &&h.active_operation_id===op.operation_id&&latest.actor_id===op.actor_id
      &&latest.site_id===op.site_id&&latest.kind===op.kind&&latest.release_id===op.release_id;
  }
  async function verifyRelease(bucket,op){
    if(op.kind==='private')return;
    const r=await db.release(op.site_id,op.release_id);
    if(!r||!r.approved_at||(op.kind==='rollback'&&!r.published_at))throw new Error('Approved release identity is missing');
    const manifest=await verifyStagedRelease({bucket,siteId:op.public_site_id,releaseId:op.release_id});
    const body=await bucket.get(`sites/${op.public_site_id}/release-manifests/${op.release_id}.json`);
    if(!body||await hash(await body.text())!==r.manifest_sha256)throw new Error('Frozen release manifest changed');
    return manifest;
  }
  const matches=(p,op)=>!!p&&p.publication_id===op.operation_id&&p.site_id===op.public_site_id
    &&p.status===(op.kind==='private'?'private':'live')&&p.release===op.release_id;
  const fenced=(p,op)=>!!p&&p.publication_id===op.fence_id&&p.site_id===op.public_site_id
    &&p.status===(op.base_pointer?.status??'private')&&p.release===(op.base_pointer?.release??null);
  async function finish(op,bucket,pointer,isFence=false){
    if(isFence?!fenced(pointer,op):!matches(pointer,op))throw new Error('Unconfirmed publication pointer');
    if(!isFence)await verifyRelease(bucket,op);
    const result=await rpc('finalize',{p_operation:op.operation_id,p_pointer:pointer,p_fenced:isFence});
    return {ok:true,operation_id:op.operation_id,state:result.state,public_url:op.public_url,release_id:pointer.release};
  }
  async function operationContext(siteId,operationId,actorId){
    const [op,h]=await Promise.all([db.operation(operationId),db.hosting(siteId)]);
    if(!op||!h||op.site_id!==siteId)throw new Error('Publication operation not found for this site');
    // Revalidate current administrator membership even for an idempotent recovery request.
    await rpc('require_admin',{p_actor:actorId});
    return {...op,public_site_id:h.public_site_id,public_url:h.public_url};
  }
  async function reconcile({siteId,operationId,actorId}){
    if(!uuid.test(operationId||'')||!uuid.test(actorId||''))throw new Error('Valid operation and administrator IDs required');
    const op=await operationContext(siteId,operationId,actorId);
    if(['committed','fenced'].includes(op.state))return {ok:true,operation_id:op.operation_id,state:op.state,public_url:op.public_url,release_id:op.result_pointer?.release??null};
    const bucket=storeForSite(op.public_site_id);
    try{
      if(!await authorize(op,actorId))throw new Error('Publication operation lock changed');
      let p=await readPublication({bucket,siteId:op.public_site_id});
      if(matches(p,op))return await finish(op,bucket,p);
      if(fenced(p,op))return await finish(op,bucket,p,true);
      // A GET showing the old state is NOT proof the timed-out write cannot still arrive.
      // Use the EXACT baseline persisted before the attempt. Never fence a freshly read winner.
      try{
        await fencePublication({bucket,siteId:op.public_site_id,expectedPointer:op.base_pointer,
          publicationId:op.fence_id,authorize:()=>authorize(op,actorId)});
      }catch{
        // Either the original write or our fence may have succeeded with a lost response.
        // An unrelated winner is never overwritten and leaves the lock for investigation.
      }
      p=await readPublication({bucket,siteId:op.public_site_id});
      if(matches(p,op))return await finish(op,bucket,p);
      if(fenced(p,op))return await finish(op,bucket,p,true);
      throw new Error('R2 publication still has an unrecognized result');
    }catch(e){throw await uncertain(op.operation_id,e);}
  }
  async function publish({siteId,actorId,releaseId,kind='publish',operationId=crypto.randomUUID()}){
    if(!uuid.test(operationId)||!uuid.test(actorId||''))throw new Error('Valid operation and administrator IDs required');
    const h=await db.hosting(siteId);
    if(!h)throw new Error('Site has no Cloudflare hosting mapping');
    const bucket=storeForSite(h.public_site_id);
    const base=await readPublication({bucket,siteId:h.public_site_id});
    const op=await rpc('claim',{p_actor:actorId,p_site:siteId,p_operation:operationId,p_kind:kind,p_release:releaseId,p_base:base});
    // A repeated operation is reconciled, NEVER sent to R2 as a second publication attempt.
    if(op.reused)return reconcile({siteId,actorId,operationId});
    try{
      await verifyRelease(bucket,op);
      const args={bucket,siteId:op.public_site_id,expectedCurrentRelease:base?.release??null,
        expectedPublicationId:base?.publication_id??null,publicationId:op.operation_id,authorize:()=>authorize(op)};
      if(kind==='private')await deactivateRelease(args);
      else await activateRelease({...args,releaseId:op.release_id});
      const current=await readPublication({bucket,siteId:op.public_site_id});
      return await finish(op,bucket,current);
    }catch(e){throw await uncertain(op.operation_id,e);}
  }
  return {publish,reconcile};
}

// Narrow PostgREST adapter: errors cannot be mistaken for empty successful responses.
export function supabaseHostingDatabase(admin){
  const one=async(table,filters)=>{
    let q=admin.from(table).select('*');for(const [key,value] of Object.entries(filters))q=q.eq(key,value);
    const {data,error}=await q.maybeSingle();if(error)throw error;return data;
  };
  return {
    rpc:async(name,args)=>{const {data,error}=await admin.rpc(name,args);if(error)throw error;return data;},
    hosting:siteId=>one('website_hosting_sites',{site_id:siteId}),
    operation:operationId=>one('website_hosting_operations',{operation_id:operationId}),
    release:(siteId,releaseId)=>one('website_hosting_releases',{site_id:siteId,release_id:releaseId})
  };
}

// Server-only publishing. The public reader must never expose these methods.
import {prepareRelease, validateAssetPath} from './hosting-release-preflight.mjs';

const SITE_ID = /^[0-9]{4,10}$/;
const RELEASE_ID = /^[a-f0-9]{12,64}$/;
const SHA256 = /^[a-f0-9]{64}$/;
const PUBLICATION_ID = /^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/;
const MAX_MANIFEST_BYTES = 256 * 1024;
const pointerKey = id => `sites/${id}/active.json`;
const manifestKey = (id, release) => `sites/${id}/release-manifests/${release}.json`;
const assetKey = (id, release, path) => `sites/${id}/releases/${release}/${path}`;

function requireStore(bucket) {
  if (!bucket || typeof bucket.get !== 'function' || typeof bucket.head !== 'function' || typeof bucket.put !== 'function') {
    throw new Error('R2 binding with get/head/put is required');
  }
}

function verifyIds(siteId, releaseId) {
  const id = String(siteId ?? ''), release = String(releaseId ?? '');
  if (!SITE_ID.test(id) || !RELEASE_ID.test(release)) throw new Error('Invalid site ID or release ID');
  return {id, release};
}

async function sha256(body) {
  const bytes = typeof body === 'string' ? new TextEncoder().encode(body) : body;
  const digest = await crypto.subtle.digest('SHA-256', bytes);
  return Array.from(new Uint8Array(digest), byte => byte.toString(16).padStart(2, '0')).join('');
}

export async function stageRelease({bucket, siteId, releaseId, files}) {
  requireStore(bucket);
  const plan = prepareRelease(siteId, releaseId, files);
  const completedKey = manifestKey(plan.site_id, plan.release);
  if (await bucket.head(completedKey)) throw new Error('Release manifest already exists');
  const entries = [];
  for (const asset of plan.objects) {
    // A partial attempt needs a fresh ID. Neither partial nor completed files are overwritten.
    if (await bucket.head(asset.key)) throw new Error(`Release key already exists: ${asset.path}`);
    const checksum = await sha256(asset.body);
    const written = await bucket.put(asset.key, asset.body, {
      onlyIf: new Headers({'If-None-Match': '*'}),
      sha256: checksum,
      customMetadata: {sha256: checksum}
    });
    if (!written) throw new Error(`Immutable release write rejected: ${asset.path}`);
    const verified = await bucket.head(asset.key);
    if (!verified || Number(verified.size) !== asset.bytes || verified.customMetadata?.sha256 !== checksum) {
      throw new Error(`R2 asset verification failed: ${asset.path}`);
    }
    entries.push({path: asset.path, bytes: asset.bytes, sha256: checksum});
  }
  const manifest = JSON.stringify({
    version: 1, site_id: plan.site_id, release: plan.release,
    total_bytes: plan.total_bytes, files: entries
  });
  const completed = await bucket.put(completedKey, manifest, {
    onlyIf: new Headers({'If-None-Match': '*'}),
    httpMetadata: {contentType: 'application/json'},
    sha256: await sha256(manifest)
  });
  if (!completed) throw new Error('Release completion write rejected');
  await verifyStagedRelease({bucket, siteId: plan.site_id, releaseId: plan.release});
  return {site_id: plan.site_id, release: plan.release, total_bytes: plan.total_bytes, file_count: plan.file_count, staged: true};
}

export async function verifyStagedRelease({bucket, siteId, releaseId}) {
  requireStore(bucket);
  const {id, release} = verifyIds(siteId, releaseId);
  const object = await bucket.get(manifestKey(id, release));
  if (!object || !Number.isSafeInteger(object.size) || object.size > MAX_MANIFEST_BYTES) {
    throw new Error('Target release has no valid completion manifest');
  }
  let manifest;
  try { manifest = JSON.parse(await object.text()); }
  catch { throw new Error('Unreadable release completion manifest'); }
  if (manifest?.version !== 1 || manifest.site_id !== id || manifest.release !== release
      || !Array.isArray(manifest.files) || !manifest.files.length || manifest.files.length > 500) {
    throw new Error('Release completion manifest does not match target');
  }
  const names = new Set();
  let total = 0;
  for (const entry of manifest.files) {
    validateAssetPath(entry.path);
    if (names.has(entry.path) || !Number.isSafeInteger(entry.bytes) || entry.bytes <= 0
        || entry.bytes > 15 * 1024 * 1024 || !SHA256.test(entry.sha256)) {
      throw new Error('Invalid asset in release completion manifest');
    }
    names.add(entry.path);
    total += entry.bytes;
    if (total > 35 * 1024 * 1024) throw new Error('Release size exceeds guardrail');
    const stored = await bucket.head(assetKey(id, release, entry.path));
    if (!stored || stored.size !== entry.bytes || stored.customMetadata?.sha256 !== entry.sha256) {
      throw new Error(`Staged asset is missing or changed: ${entry.path}`);
    }
  }
  if (!names.has('index.html') || total !== manifest.total_bytes) throw new Error('Incomplete release manifest');
  return manifest;
}

function publicationId(value) {
  const id = value === undefined ? crypto.randomUUID() : value;
  if (typeof id !== 'string' || !PUBLICATION_ID.test(id)) throw new Error('Invalid publication operation ID');
  return id;
}

function normalizedPointer(state) {
  if (!state || !['live','private'].includes(state.status)
      || !(RELEASE_ID.test(state.release || '') || (state.status === 'private' && state.release === null))
      || (state.publication_id !== undefined && !PUBLICATION_ID.test(state.publication_id || ''))) {
    throw new Error('Invalid current release object');
  }
  return {status:state.status,release:state.release,publication_id:state.publication_id ?? null};
}

export async function readPublication({bucket,siteId}) {
  requireStore(bucket);
  const id = String(siteId ?? '');
  if(!SITE_ID.test(id))throw new Error('Invalid site ID');
  const current = await bucket.get(pointerKey(id));
  if(current === null)return null;
  if(!Number.isSafeInteger(current.size) || current.size < 1 || current.size > 4096
    || typeof current.text !== 'function' || !/^"[^"\r\n]+"$/.test(current.httpEtag || '')) {
    throw new Error('Invalid current release object');
  }
  let state;
  try {state=JSON.parse(await current.text());}catch{throw new Error('Unreadable current release');}
  return {site_id:id,...normalizedPointer(state),etag:current.httpEtag};
}

async function writePublication(bucket,id,state,base) {
  const condition = base ? new Headers({'If-Match':base.etag}) : new Headers({'If-None-Match':'*'});
  const committed=await bucket.put(pointerKey(id),JSON.stringify(state),{
    onlyIf:condition,httpMetadata:{contentType:'application/json'}
  });
  if(!committed)throw new Error('Concurrent publication conflict: active release unchanged');
  return {site_id:id,...state,etag:committed.httpEtag,previous_release:base?.release ?? null,committed:true};
}

function expectedBase(current,expectedCurrentRelease,expectedPublicationId) {
  if(expectedCurrentRelease !== null && !RELEASE_ID.test(String(expectedCurrentRelease || ''))) {
    throw new Error('An explicit expected current release (or null) is required');
  }
  if(expectedPublicationId !== undefined && expectedPublicationId !== null && !PUBLICATION_ID.test(expectedPublicationId)) {
    throw new Error('Invalid expected publication operation ID');
  }
  if((current?.release ?? null) !== expectedCurrentRelease
    || (expectedPublicationId !== undefined && (current?.publication_id ?? null) !== expectedPublicationId)) {
    throw new Error('Current release changed; refusing to overwrite');
  }
}

export async function activateRelease({bucket, siteId, releaseId, expectedCurrentRelease, expectedPublicationId, publicationId:operationId, authorize}) {
  requireStore(bucket);
  const {id, release} = verifyIds(siteId, releaseId);
  if (expectedCurrentRelease !== null && !RELEASE_ID.test(String(expectedCurrentRelease || ''))) {
    throw new Error('An explicit expected current release (or null) is required');
  }
  if (typeof authorize !== 'function' || await authorize({siteId: id, releaseId: release}) !== true) {
    throw new Error('Publication was not authorized');
  }
  await verifyStagedRelease({bucket, siteId: id, releaseId: release});
  const current = await readPublication({bucket,siteId:id});
  if(current===null && expectedCurrentRelease!==null)throw new Error('Current release unexpectedly missing');
  expectedBase(current,expectedCurrentRelease,expectedPublicationId);
  const nonce=publicationId(operationId);
  if(current?.publication_id===nonce)throw new Error('Publication operation ID was already used');
  // A unique operation ID also changes the content-derived ETag on A -> B -> A.
  return writePublication(bucket,id,{status:'live',release,publication_id:nonce},current);
}

export async function deactivateRelease({bucket,siteId,expectedCurrentRelease,expectedPublicationId,publicationId:operationId,authorize}) {
  requireStore(bucket);
  const id=String(siteId ?? '');
  if(!SITE_ID.test(id))throw new Error('Invalid site ID');
  if(typeof authorize!=='function'||await authorize({siteId:id,releaseId:expectedCurrentRelease,kind:'private'})!==true) {
    throw new Error('Publication was not authorized');
  }
  const current=await readPublication({bucket,siteId:id});
  expectedBase(current,expectedCurrentRelease,expectedPublicationId);
  const nonce=publicationId(operationId);
  if(current?.publication_id===nonce)throw new Error('Publication operation ID was already used');
  return writePublication(bucket,id,{status:'private',release:current?.release ?? null,publication_id:nonce},current);
}

// Recovery barrier for a timed-out conditional write. Do not clear the DB lock based on a GET
// alone: a late write may still be in flight. Winning this CAS invalidates its old condition.
export async function fencePublication({bucket,siteId,expectedPointer,publicationId:operationId,authorize}) {
  requireStore(bucket);
  const id=String(siteId ?? '');
  if(!SITE_ID.test(id)||expectedPointer===undefined)throw new Error('Explicit recovery snapshot is required');
  if(typeof authorize!=='function'||await authorize({siteId:id,kind:'fence'})!==true)throw new Error('Publication was not authorized');
  const nonce=publicationId(operationId);
  let state={status:'private',release:null,publication_id:nonce};
  if(expectedPointer!==null) {
    if(expectedPointer.site_id!==id || !/^"[^"\r\n]+"$/.test(expectedPointer.etag || '')) {
      throw new Error('Recovery snapshot does not match site');
    }
    const prior=normalizedPointer({...expectedPointer,publication_id:expectedPointer.publication_id ?? undefined});
    if(prior.publication_id===nonce)throw new Error('Recovery needs a fresh publication operation ID');
    state={status:prior.status,release:prior.release,publication_id:nonce};
  }
  return {...await writePublication(bucket,id,state,expectedPointer),fenced:true};
}

// Server-only export. Callers must check customer/admin access before downloading.
export async function exportStagedRelease({bucket, siteId, releaseId}) {
  const manifest = await verifyStagedRelease({bucket, siteId, releaseId});
  const files = [];
  for (const entry of manifest.files) {
    const object = await bucket.get(assetKey(manifest.site_id, manifest.release, entry.path));
    if (!object) throw new Error(`Backup asset is missing: ${entry.path}`);
    const content = new Uint8Array(await object.arrayBuffer());
    if (content.byteLength !== entry.bytes || await sha256(content) !== entry.sha256) {
      throw new Error(`Backup checksum verification failed: ${entry.path}`);
    }
    files.push({path: entry.path, content});
  }
  return {site_id: manifest.site_id, release: manifest.release, files};
}

// Provider-independent release package preflight.
// This module NEVER uploads assets or changes a live site's active.json.
import {auditHostedContent} from './hosting-content-audit.mjs';
const ID=/^[0-9]{4,10}$/,RELEASE=/^[a-f0-9]{12,64}$/;
const ALLOWED=new Set(["html","css","js","mjs","json","txt","svg","png","jpg","jpeg","webp","gif","ico","avif","woff","woff2","pdf","mp4","webm"]);
const TEXT_FORMATS=new Set(["html","css","js","mjs","json","txt","svg"]);

export function validateAssetPath(name){
  if(typeof name!=="string"||!name||name.length>300||name.startsWith("/")||name.includes("//")
     ||!(/^[A-Za-z0-9._/-]+$/).test(name)
     ||name.split("/").some(part=>!part||part==="."||part===".."||part.startsWith("."))){
    throw new Error("Unsafe asset path: "+name);
  }
  const extension=name.slice(name.lastIndexOf(".")+1).toLowerCase();
  if(!ALLOWED.has(extension))throw new Error("Asset format not allowed: "+name);
  return extension;
}

export function prepareRelease(siteId,releaseId,files){
  const id=String(siteId||""),version=String(releaseId||"");
  if(!ID.test(id)||!RELEASE.test(version))throw new Error("Invalid site ID or release ID");
  if(!Array.isArray(files)||files.length===0||files.length>500)throw new Error("Invalid release file count");
  const names=new Set();let totalBytes=0,hasHome=false;
  const objects=[];
  for(const item of files){
    const name=String(item?.path||"");
    const extension=validateAssetPath(name);
    if(names.has(name))throw new Error("Duplicate asset path: "+name);
    const body=item?.content;
    if(typeof body!=="string"&&!(body instanceof Uint8Array))throw new Error("Invalid asset content: "+name);
    const size=typeof body==="string"?new TextEncoder().encode(body).byteLength:body.byteLength;
    if(size===0||size>15*1024*1024)throw new Error("Empty or oversized asset: "+name);
    totalBytes+=size;if(totalBytes>35*1024*1024)throw new Error("Release size exceeds guardrail");
    if(name==="index.html")hasHome=true;
    if(TEXT_FORMATS.has(extension)){
      const source=typeof body==="string"?body:new TextDecoder("utf-8",{fatal:true}).decode(body);
      if(extension==="html"&&(!/<!doctype\s+html/i.test(source)||!/<html\b/i.test(source)))
        throw new Error("Missing HTML document structure: "+name);
      if(/sho-support\.github\.io\/(?:site-|website-|admin\/)|sho-web-support\.netlify\.app\/(?:website-|admin\/)/i.test(source))
        throw new Error("Legacy management or provider URL embedded: "+name);
    }
    names.add(name);
    objects.push({key:"sites/"+id+"/releases/"+version+"/"+name,path:name,body,bytes:size});
  }
  if(!hasHome)throw new Error("Home page is missing");
  auditHostedContent(files);
  return {site_id:id,release:version,total_bytes:totalBytes,file_count:files.length,objects,
    activation:{key:"sites/"+id+"/active.json",json:JSON.stringify({status:"live",release:version})}};
}

// Conservative first-sale static-site policy. This is a deny-list review aid, not a JS sandbox.
// Tenant origin isolation and keeping every account/session secret out of the site are essential.
export function auditHostedContent(files){
  const errors=[];
  for(const f of files){
    if(!/\.(?:html?|css|m?js|json|svg)$/i.test(f.path))continue;
    const s=typeof f.content==='string'?f.content:new TextDecoder('utf-8',{fatal:true}).decode(f.content);
    const rules=[
      [/\b(?:gh[pousr]_[A-Za-z0-9]{20,}|sk-(?:proj-)?[A-Za-z0-9_-]{24,}|sb_secret_[A-Za-z0-9_-]{20,})\b/,'credential-like value'],
      [/https?:\/\/[^\s"'<>]*\.supabase\.co\b/i,'backend project URL'],
      [/\b(?:document\s*\.\s*cookie|localStorage|sessionStorage|indexedDB|serviceWorker)\b/i,'browser account/storage access'],
      [/\b(?:eval\s*\(|new\s+Function\s*\(|importScripts\s*\(|import\s*\()/i,'dynamic code execution'],
      [/\b(?:fetch\s*\(|XMLHttpRequest|WebSocket|sendBeacon\s*\()/i,'unreviewed script network access'],
      [/<script\b[^>]*\bsrc\s*=\s*["']\s*(?:https?:|\/\/|data:)/i,'external script'],
      [/\b(?:javascript|vbscript)\s*:/i,'executable link'],
      [/<(?:iframe|object|embed)\b[^>]*(?:src|data)\s*=\s*["']\s*(?:data:|javascript:)/i,'executable embedded document'],
      [/\b(?:srcdoc|onerror)\s*=/i,'unreviewed executable HTML attribute']
    ];
    for(const [pattern,reason] of rules)if(pattern.test(s))errors.push({path:f.path,reason});
  }
  if(errors.length)throw new Error('Hosted content needs security review: '+errors.map(e=>e.path+' ('+e.reason+')').join('; '));
  return {ok:true,policy:'static-site-first-sale-v1',files:files.length};
}

